import React from "react";
import { Link } from "react-scroll";
function Navbar() {
  return (
    <nav className="navbar">
      <h2>Radhika S</h2>
      <ul>
        <li> <Link to="home" smooth={true} duration={1000}>
            Home
          </Link></li>
        <li><Link to="about" smooth={true} duration={1000}>
            About
          </Link></li>
        <li><Link to="projects" smooth={true} duration={1000}>
            Projects
          </Link></li>
        <li><Link to="contact" smooth={true} duration={1000}>
            Contact
          </Link></li>
      </ul>
    </nav>
  );
}

export default Navbar;